  if(!handguns.isEmpty()&&CorpseBalance35.pick(world,3)!=0)return c(ZoneReflection.type("dev.zomboid.remains.GunAccess"),"create",handguns.get(CorpseBalance35.pick(world,handguns.size())),0);
